private ComponentMenuBo buildMenuBo(Map<String, Object> map) {
    ComponentMenuBo bo = new ComponentMenuBo();
    bo.setId(MapUtils.getLong(map, "id"));
    bo.setMenuName(MapUtils.getString(map, "c_menu_name"));
    // 加字段不改结构：菜单接口本来返回 List<Map>，加一列就多一个 key
    bo.setMenuGroup(MapUtils.getString(map, "c_menu_group"));
    bo.setCategory(MapUtils.getString(map, "c_category"));
    bo.setFavorite(MapUtils.getInteger(map, "c_favorite"));
    bo.setFavoriteSort(MapUtils.getInteger(map, "c_favorite_sort"));
    return bo;
}
